-- Algorithm A: initializes max to 0
PROCEDURE findMaxA(aList)
{
   max ← 0
   FOR EACH item IN aList
   {
      IF(item > max)
      {
         max ← item
      }
   }
   RETURN max
}

-- Algorithm B: initializes max to first element
PROCEDURE findMaxB(aList)
{
   max ← aList[1]
   FOR EACH item IN aList
   {
      IF(item > max)
      {
         max ← item
      }
   }
   RETURN max
}

-- For aList = [5, 3, 8, 2]:
-- Algorithm A: max starts at 0, finds 8 → returns 8 ✓
-- Algorithm B: max starts at 5, finds 8 → returns 8 ✓
-- Both give the same result here!

-- For aList = [-5, -3, -8, -2]:
-- Algorithm A: max starts at 0. -5>0? No. -3>0? No. -8>0? No. -2>0? No.
--              returns 0  ← WRONG! 0 is not even in the list!
-- Algorithm B: max starts at -5. -3>-5? Yes, max=-3. -8>-3? No. -2>-3? Yes, max=-2.
--              returns -2 ← CORRECT!

